def solve(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Identify wall value (most common non-background? or find pattern)
    # From demos: 9 is wall, 1 is background -> output uses 3 for filled
    # For test: 8 is likely background, 7 is wall (single digit different)

    # Let's analyze what values exist
    all_vals = set()
    for row in grid:
        all_vals.update(row)
    print("All values in grid:", all_vals)

    # In demo pair 1: input has {1, 9}, output has {1, 3, 9}
    # In test: input has {8, 7}, so output should have {8, 3, 7}
    # where 7 acts as 9, 8 acts as 1, and 8 between 7s becomes 3

    WALL = max(all_vals - {min(all_vals)})  # likely 7 or 9
    BG = min(all_vals)  # likely 1 or 8

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if result[r][c] == BG:
                # Check if this cell is between walls (horizontally)
                left_has_wall = False
                right_has_wall = False

                # Look left for a wall
                for lc in range(c-1, -1, -1):
                    if result[r][lc] == WALL:
                        left_has_wall = True
                        break
                    elif result[r][lc] != BG:
                        # Non-BG but not WALL - treat as blocking
                        break

                # Look right for a wall
                for rc in range(c+1, cols):
                    if result[r][rc] == WALL:
                        right_has_wall = True
                        break
                    elif result[r][rc] != BG:
                        break

                if left_has_wall and right_has_wall:
                    result[r][c] = 3

    return result

